                int v = to[e];
                if (!removed[v] && parent[v] == u)
                    subtree[u] += subtree[v];
            }
        }

        int centroid = start;
        int best_part = count + 1;
        for (int i = 0; i < count; ++i) {
            int u = order[i];
            int largest = count - subtree[u];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (!removed[v] && parent[v] == u && subtree[v] > largest)
                    largest = subtree[v];
            }
            if (largest < best_part) {
                best_part = largest;
                centroid = u;
            }
        }

        top = 0;
        stack[top++] = centroid;
        parent[centroid] = -1;
        tmp_dist[centroid] = 0;

        while (top) {
            int u = stack[--top];
            size_t pos = (size_t)u * MAX_LOG + level;
            centroid_anc[pos] = centroid;
            centroid_dist[pos] = tmp_dist[u];

            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (removed[v] || v == parent[u]) continue;
                parent[v] = u;
                tmp_dist[v] = tmp_dist[u] + 1;
                stack[top++] = v;
            }
        }

        removed[centroid] = 1;
        for (int e = head[centroid]; e != -1; e = next[e]) {
            int v = to[e];
            if (!removed[v]) {
                task_start[tasks] = v;
                task_level[tasks++] = level + 1;
            }
        }
    }

    int *nearest = malloc((size_t)n * sizeof(int));
    int low = 0, high = n - 1;

    while (low < high) {
        int radius = low + (high - low) / 2;
        for (int i = 0; i < n; ++i) nearest[i] = n + 1;

        int centers = 0;
        int feasible = 1;

        for (int i = 0; i < n; ++i) {
            int v = order[i];
            int best = n + 1;

            for (int j = 0; j < MAX_LOG; ++j) {
                size_t pos = (size_t)v * MAX_LOG + j;
                int c = centroid_anc[pos];
                if (c == -1) break;
                int d = centroid_dist[pos] + nearest[c];
                if (d < best) best = d;
            }

            if (best > radius) {
                if (++centers > k) {
                    feasible = 0;
                    break;
                }

                int c = v;
                int steps = radius;
                for (int bit = 0; steps; ++bit, steps >>= 1) {
                    if (steps & 1)
                        c = up[(size_t)bit * n + c];
                }

                for (int j = 0; j < MAX_LOG; ++j) {
                    size_t pos = (size_t)c * MAX_LOG + j;
                    int centroid = centroid_anc[pos];
                    if (centroid == -1) break;
                    if (centroid_dist[pos] < nearest[centroid])
                        nearest[centroid] = centroid_dist[pos];
                }
            }
        }

        if (feasible) high = radius;
        else low = radius + 1;
    }

    printf("%d\n", low);

    free(head);
    free(to);
    free(next);
    free(depth);
    free(up);
    free(stack);
    free(order);
    free(centroid_anc);
    free(centroid_dist);
    free(parent);
    free(subtree);
    free(tmp_dist);
    free(removed);
    free(task_start);
    free(task_level);
    free(nearest);
    return 0;
}
